    BANK_SAFE c;
    bool rejectPayments;

    function setUp() public {
        c = new BANK_SAFE();
    }

    function _run(uint256 amount) internal {
        amount = bound(amount, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= amount);
        try c.SetMinSum(0) {} catch { return; }
        try c.Deposit{value: amount}() {} catch { return; }
        uint256 balBefore;
        try c.balances(address(this)) returns (uint256 __r) { balBefore = __r; } catch { return; }
        uint ethBefore = address(c).balance;
        rejectPayments = true;
        bool reverted;
        try c.Collect(amount) { reverted = false; }
        catch { reverted = true; }
        uint256 balAfter;
        try c.balances(address(this)) returns (uint256 __r) { balAfter = __r; } catch { return; }
        uint ethAfter = address(c).balance;
        rejectPayments = false;
        assertTrue(reverted && balAfter == balBefore && ethAfter == ethBefore);
    }

    function testFuzz_run(uint256 amount) public {
        _run(amount);
